create function private.can_read_driver_pickup_shipment(target bigint) returns boolean language sql stable security definer set search_path='' as $$ select (select private.is_active_mobile_driver()) and exists(select 1 from public.pickup_manifest_items i join public.pickup_manifests m on m.id=i.manifest_id where i.shipment_id=target and m.assigned_driver_id=(select auth.uid()) and m.organization_id=(select private.current_organization_id())); $$; revoke all on function private.can_read_driver_pickup_shipment(bigint) from public,anon; grant execute on function private.can_read_driver_pickup_shipment(bigint) to authenticated; create policy assigned_driver_pickup_shipments on public.shipments for select to authenticated using(organization_id=(select private.current_organization_id()) and (select private.can_read_driver_pickup_shipment(id)));
